                            g[p*i+r][pc*j+c]=grid[p*i+r][pc*j+c]
    # mark 8s
    for i in range(min(nb,s)):
        for j in range(min(nc,s)):
            if shape[i][j]:
                r,c=p*i+i, pc*j+j
                if r<H and c<W: g[r][c]=8
    return g

